{"file_path":"src/expand.js","content":"/** URI template expansion following the operator table. */

import { UriTemplateError, parse } from './parse.js';

const RULES = {
  '': { first: '', separator: ',', named: false, ifEmpty: '', allowReserved: false },
  '+': { first: '', separator: ',', named: false, ifEmpty: '', allowReserved: true },
  '#': { first: '#', separator: ',', named: false, ifEmpty: '', allowReserved: true },
  '.': { first: '.', separator: '.', named: false, ifEmpty: '', allowReserved: false },
  '/': { first: '/', separator: '/', named: false, ifEmpty: '', allowReserved: false },
  ';': { first: ';', separator: ';', named: true, ifEmpty: '', allowReserved: false },
  '?': { first: '?', separator: '&', named: true, ifEmpty: '=', allowReserved: false },
  '&': { first: '&', separator: '&', named: true, ifEmpty: '=', allowReserved: false },
};

const UNRESERVED = /^[A-Za-z0-9\-._~]$/;
const RESERVED = /^[:/?#[\]@!$&'()*+,;=]$/;

/**
 * Percent-encode text as uppercase UTF-8 triplets.
 *
 * @param {string} text source text
 * @param {boolean} allowReserved keep reserved characters and existing percent-triplets
 * @returns {string} the encoded text
 */
function encode(text, allowReserved) {
  let out = '';
  let i = 0;
  while (i < text.length) {
    const char = String.fromCodePoint(text.codePointAt(i));
    i += char.length;
    if (UNRESERVED.test(char)) {
      out += char;
      continue;
    }
    if (allowReserved) {
      if (RESERVED.test(char)) {
        out += char;
        continue;
      }
      if (char === '%' && /^[0-9A-Fa-f]{2}/.test(text.slice(i))) {
        out += `%${text.slice(i, i + 2).toUpperCase()}`;
        i += 2;
        continue;
      }
    }
    out += encodeURIComponent(char)
      .split('')
      .map((piece) => (piece === '%' ? '%' : piece))
      .join('')
      .replace(/[^%0-9A-Fa-f]/g, (raw) =>
        Array.from(new TextEncoder().encode(raw))
          .map((byte) => `%${byte.toString(16).toUpperCase().padStart(2, '0')}`)
          .join(''),
      )
      .toUpperCase();
  }
  return out;
}

/**
 * Convert a scalar value to its text form.
 *
 * @param {unknown} value candidate value
 * @param {string} name variable name, for error reporting
 * @returns {string} the text form
 */
function scalarText(value, name) {
  if (typeof value === 'string') return value;
  if (typeof value === 'number' && Number.isFinite(value)) return String(value);
  if (typeof value === 'boolean') return String(value);
  throw new UriTemplateError(`value for '${name}' is not a string, number or boolean`);
}

/**
 * Truncate a string to a number of code points.
 *
 * @param {string} text source text
 * @param {number | null} maxLength limit, or null for none
 * @returns {string} the truncated text
 */
function truncate(text, maxLength) {
  if (maxLength === null) return text;
  return Array.from(text).slice(0, maxLength).join('');
}

/**
 * Render `name=value`, honouring the empty-value text of a named operator.
 *
 * @param {string} name variable or key name, already encoded as needed
 * @param {string} value encoded value
 * @param {{ ifEmpty: string }} rule operator rule
 * @returns {string} the rendered pair
 */
function pair(name, value, rule) {
  return value === '' ? `${name}${rule.ifEmpty}` : `${name}=${value}`;
}

/**
 * Build the pieces contributed by one variable.
 *
 * @param {{ name: string, explode: boolean, maxLength: number | null }} variable variable spec
 * @param {unknown} value bound value
 * @param {object} rule operator rule
 * @returns {string[]} the pieces, possibly empty
 */
function piecesFor(variable, value, rule) {
  const { name, explode, maxLength } = variable;
  const enc = (text) => encode(text, rule.allowReserved);
  if (Array.isArray(value)) {
    const items = value.filter((item) => item !== null && item !== undefined);
    if (items.length === 0) return [];
    if (maxLength !== null) {
      throw new UriTemplateError(`prefix modifier applied to a composite value: '${name}'`);
    }
    const encoded = items.map((item) => enc(scalarText(item, name)));
    if (!explode) {
      const joined = encoded.join(',');
      return [rule.named ? pair(name, joined, rule) : joined];
    }
    return encoded.map((item) => (rule.named ? pair(name, item, rule) : item));
  }
  if (typeof value === 'object') {
    const entries = Object.entries(value).filter(([, item]) => item !== null && item !== undefined);
    if (entries.length === 0) return [];
    if (maxLength !== null) {
      throw new UriTemplateError(`prefix modifier applied to a composite value: '${name}'`);
    }
    const encoded = entries.map(([key, item]) => [enc(key), enc(scalarText(item, name))]);
    if (!explode) {
      const joined = encoded.flat().join(',');
      return [rule.named ? pair(name, joined, rule) : joined];
    }
    return encoded.map(([key, item]) => (rule.named ? pair(key, item, rule) : `${key}=${item}`));
  }
  const text = enc(truncate(scalarText(value, name), maxLength));
  return [rule.named ? pair(name, text, rule) : text];
}

/**
 * Expand a template against a set of variables.
 *
 * @param {string} template template text
 * @param {Record<string, unknown>} variables values bound by name, read as own properties
 * @returns {string} the expanded URI
 */
export function expand(template, variables) {
  const parts = parse(template);
  if (typeof variables !== 'object' || variables === null) {
    throw new UriTemplateError('variables must be an object');
  }
  let out = '';
  for (const part of parts) {
    if (part.type === 'literal') {
      out += encode(part.value, true);
      continue;
    }
    const rule = RULES[part.operator];
    const pieces = [];
    for (const variable of part.variables) {
      if (!Object.prototype.hasOwnProperty.call(variables, variable.name)) continue;
      const value = variables[variable.name];
      if (value === null || value === undefined) continue;
      pieces.push(...piecesFor(variable, value, rule));
    }
    if (pieces.length === 0) continue;
    out += rule.first + pieces.join(rule.separator);
  }
  return out;
}
"}

