/** Failure raised while parsing or expanding a template. */
export class UriTemplateError extends Error {
  /**
   * @param {string} message reason
   * @param {number} [index] 0-based index of the `{` that opens the offending expression
   */
  constructor(message, index) {
    super(message);
    this.name = 'UriTemplateError';
    this.index = index;
  }
}

const OPERATORS = ['+', '#', '.', '/', ';', '?', '&'];
const RESERVED_OPERATORS = ['=', ',', '!', '@', '|'];
const VARCHAR = '(?:[A-Za-z0-9_]|%[0-9A-Fa-f]{2})';
const NAME_RE = new RegExp(`^${VARCHAR}+(?:\\.${VARCHAR}+)*$`);

/**
 * Parse a single variable specification such as `a:3` or `b*`.
 *
 * @param {string} spec specification text
 * @param {number} index index of the opening brace, for error reporting
 * @returns {{ name: string, explode: boolean, maxLength: number | null }} the variable
 */
function parseVariable(spec, index) {
  if (spec === '') throw new UriTemplateError(`empty variable specification at ${index}`, index);
  let name = spec;
  let explode = false;
  let maxLength = null;
  let modifier = null;
  if (name.endsWith('*')) {
    explode = true;
    name = name.slice(0, -1);
  } else {
    const colon = name.indexOf(':');
    if (colon !== -1) {
      modifier = name.slice(colon + 1);
      name = name.slice(0, colon);
    }
  }
  if (!NAME_RE.test(name)) throw new UriTemplateError(`invalid variable name '${name}' at ${index}`, index);
  if (modifier !== null) {
    if (!/^[1-9][0-9]{0,3}$/.test(modifier)) {
      throw new UriTemplateError(`invalid prefix modifier ':${modifier}' at ${index}`, index);
    }
    maxLength = Number(modifier);
  }
  return { name, explode, maxLength };
}

/**
 * Parse the inside of a `{...}` group.
 *
 * @param {string} body text between the braces
 * @param {number} index index of the opening brace
 * @returns {{ type: 'expression', operator: string, variables: object[] }} the expression part
 */
function parseExpression(body, index) {
  if (body === '') throw new UriTemplateError(`empty expression at ${index}`, index);
  let operator = '';
  let rest = body;
  const first = body[0];
  if (OPERATORS.includes(first)) {
    operator = first;
    rest = body.slice(1);
  } else if (RESERVED_OPERATORS.includes(first)) {
    throw new UriTemplateError(`reserved operator '${first}' at ${index}`, index);
  }
  const variables = rest.split(',').map((spec) => parseVariable(spec, index));
  return { type: 'expression', operator, variables };
}

/**
 * Split a template into literal and expression parts.
 *
 * @param {string} template template text
 * @returns {({ type: 'literal', value: string } | { type: 'expression', operator: string, variables: object[] })[]}
 *   the parts in order, with adjacent literal text merged
 */
export function parse(template) {
  if (typeof template !== 'string') throw new UriTemplateError('template must be a string');
  const parts = [];
  let literal = '';
  let index = 0;
  const flush = () => {
    if (literal !== '') parts.push({ type: 'literal', value: literal });
    literal = '';
  };
  while (index < template.length) {
    const char = template[index];
    if (char === '{') {
      const close = template.indexOf('}', index + 1);
      if (close === -1) throw new UriTemplateError(`unterminated expression at ${index}`, index);
      flush();
      parts.push(parseExpression(template.slice(index + 1, close), index));
      index = close + 1;
    } else if (char === '}') {
      throw new UriTemplateError(`unexpected '}' at ${index}`, index);
    } else {
      literal += char;
      index += 1;
    }
  }
  flush();
  return parts;
}
